import numpy as np

def softmax_T(logits,T):
    if not np.isfinite(T) or T<=0:
        raise ValueError('Temperature must be positive and finite')
    z=np.asarray(logits,dtype=float)/T
    w=np.exp(z-z.max())
    return w/w.sum()

