import numpy as np

def legal(costs,in_hand,elixir):
    return np.asarray(in_hand,dtype=bool) & (np.asarray(costs)<=elixir)

import numpy as np

def draw_cards(probabilities,seed,n):
    rng=np.random.default_rng(seed)
    return rng.choice(len(probabilities),size=n,p=probabilities).tolist()
